import logging
import queue
import threading

log = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Runs a callback against every item put on the queue, on one thread."""

    def __init__(self, callback, work_queue=None, name="queue-worker"):
        self._callback = callback
        self._queue = work_queue if work_queue is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()

    def submit(self, item):
        self._queue.put(item)

    def _run(self):
        while True:
            item = self._queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self._callback(item)
            except Exception:
                # One bad item must not kill the thread; the queue keeps draining.
                log.exception("callback failed for item %r", item)
            finally:
                self._queue.task_done()

    def join(self):
        self._queue.join()

    def stop(self, timeout=None):
        """Drain what is queued, then shut the thread down."""
        if not self._started:
            return
        self._queue.put(_SHUTDOWN)
        self._thread.join(timeout)
        if self._thread.is_alive():
            raise TimeoutError("worker did not stop within %s seconds" % timeout)
        self._started = False

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
